-- @context-decision: rewritten-as-blank — the topic (local/state business-attraction
-- incentives) applies to each person and each record WAS read this pass; none carried
-- evidence of the incentive-offering position any chair asserts (all were direction-only
-- deregulation/tax-cut/party inference), so each context is a documented blank naming what
-- was checked. No answer row remains.

-- GUARD: check-stance-sources.mjs ORPHAN_CONTEXT predicate, applied to the blanked pairs.
DO $$
DECLARE new_orphans int;
BEGIN
  SELECT count(*) INTO new_orphans
    FROM ed_blank t
    JOIN inform.politician_context pc ON pc.politician_id=t.pid AND pc.topic_id=t.tid
   WHERE coalesce(cardinality(pc.sources),0) > 0
     AND pc.reasoning !~* '^researched\s+[0-9]{4}-[0-9]{2}-[0-9]{2}'
     AND pc.reasoning !~* 'no (scorable |substantive |specific |detailed )?public record|no public statements? found|no record found|no scorable|unable to place|insufficient public record|no substantive [a-z ]{0,40}(available|found)';
  IF new_orphans > 0 THEN
    RAISE EXCEPTION 'CA_0107 context guard: % blanked row(s) kept reasoning that still asserts a position', new_orphans;
  END IF;
END $$;

-- ── 4. Post-verify ───────────────────────────────────────────────────────────
DO $$
DECLARE tid uuid := 'eb3d1247-0de1-4b7f-baec-7259861efd53'; c1 int; c2 int; c3 int; c4 int; c5 int; stillseated int; pinned uuid;
BEGIN
  SELECT count(*) INTO stillseated FROM ed_blank b JOIN inform.politician_answers a ON a.politician_id=b.pid AND a.topic_id=b.tid;
  IF stillseated <> 0 THEN RAISE EXCEPTION 'CA_0107 verify: % blanked pair(s) still seated', stillseated; END IF;
  SELECT count(*) FILTER (WHERE value=1), count(*) FILTER (WHERE value=2), count(*) FILTER (WHERE value=3),
         count(*) FILTER (WHERE value=4), count(*) FILTER (WHERE value=5)
    INTO c1,c2,c3,c4,c5 FROM inform.politician_answers WHERE topic_id=tid AND value IS DISTINCT FROM 0;
  IF (c1,c2,c3,c4,c5) <> (40,304,234,84,3) THEN
    RAISE EXCEPTION 'CA_0107 verify: chair counts are %/%/%/%/% (expected 40/304/234/84/3)', c1,c2,c3,c4,c5; END IF;
  SELECT topic_revision_id INTO pinned FROM inform.season_questions WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id=tid;
  IF pinned <> 'af855dba-96f3-4fa0-beb7-43c5edb3f499' THEN RAISE EXCEPTION 'CA_0107 verify: Season 2 pin is % (expected re-fork v2)', pinned; END IF;
  RAISE NOTICE 'CA_0107 post-verify OK: 16 moves, 34 blanks, 1 reasoning refresh; distribution 40/304/234/84/3; Season 2 still pins v2. Season 1 seatings corrected in place.';
END $$;

COMMIT;
